const crypto = require('crypto');
const item = $input.first().json;
const hdrs = item.headers || {};
const apiKey =
  hdrs['x-api-key'] ||
  hdrs['X-API-KEY'] ||
  hdrs['x-apikey'] ||
  '';
const expected = String($env.CASTUO_ORCHESTRATOR_API_KEY || '').trim();
if (expected && apiKey !== expected) {
  throw new Error('Orquestador: API key no válida');
}
const raw = item.body && typeof item.body === 'object' ? { ...item.body } : { ...item };
const route = String(raw.orchestrator_route || raw.route || raw.request_type || 'sensor-data').replace(/^\/+/, '');
const usesDataWrapper = raw.data != null && typeof raw.data === 'object' && !Array.isArray(raw.data);
let forward_body = usesDataWrapper ? { ...raw.data } : { ...raw };
delete forward_body.orchestrator_route;
delete forward_body.route;
delete forward_body.request_type;
if (!usesDataWrapper) {
  delete forward_body.data;
}

const routeAliases = {
  'simulacion-root': 'simulacion/computational-simulation',
  'drones-command': 'fotogrametria/drone-mission',
  'satelite-ndvi': 'satellite-ndvi'
};
const routeKey = routeAliases[route] || route;

const routes = {
  'sensor-data': '/webhook/sensor-data',
  sensores: '/webhook/sensor-data',
  'trazabilidad/sensor-data': '/webhook/trazabilidad/sensor-data',
  trazabilidad: '/webhook/trazabilidad/sensor-data',
  'fotogrametria/drone-mission': '/webhook/fotogrametria/drone-mission',
  'simulacion/computational-simulation': '/webhook/simulacion/computational-simulation',
  'satelite/coordinates': '/webhook/satelite/coordinates',
  'satellite-ndvi': '/webhook/satelite/coordinates',
  'geoespacial/process': '/webhook/geoespacial/process',
  'typeform-lead': '/webhook/typeform-lead',
  'api/query': '/webhook/api/query',
  'trillizo/audit-rotation': '/webhook/audit-rotation',
  'trillizo/shadow-check': '/webhook/shadow-check'
};

function validatePayload(routeKey, b) {
  if (!b || typeof b !== 'object') return 'Body inválido';
  if (routeKey === 'trillizo/audit-rotation' || routeKey === 'trillizo/shadow-check') return null;
  if (routeKey === 'sensor-data' || routeKey === 'sensores') {
    if (b.sensor_type != null && b.value !== undefined) {
      const n = Number(b.value);
      if (!Number.isFinite(n)) return 'sensor-data: value debe ser numérico si viaja sensor_type';
    }
    return null;
  }
  if (routeKey === 'trazabilidad/sensor-data' || routeKey === 'trazabilidad') {
    if (b.data != null && b.source == null) return 'trazabilidad: source requerido si envías data';
    return null;
  }
  if (routeKey === 'satellite-ndvi' || routeKey === 'satelite/coordinates') {
    if (b.bbox != null && !Array.isArray(b.bbox)) return 'satellite: bbox debe ser array';
    if (b.coordenadas != null && (b.coordenadas.lat === undefined || b.coordenadas.lon === undefined))
      return 'satellite: coordenadas.lat y .lon requeridos si envías coordenadas';
    return null;
  }
  return null;
}

function webhookBaseForRoute(routeKey) {
  const fallback = String($env.N8N_WEBHOOK_BASE || $env.WEBHOOK_URL || '').replace(/\/+$/, '');
  let specific = '';
  if (['sensor-data', 'sensores', 'trazabilidad/sensor-data', 'trazabilidad'].includes(routeKey)) {
    specific = String($env.N8N_WEBHOOK_BASE_SENSORES || '').replace(/\/+$/, '');
  } else if (['satelite/coordinates', 'satellite-ndvi', 'geoespacial/process'].includes(routeKey)) {
    specific = String($env.N8N_WEBHOOK_BASE_SATELITES || '').replace(/\/+$/, '');
  } else if (routeKey === 'fotogrametria/drone-mission') {
    specific = String($env.N8N_WEBHOOK_BASE_DRONES || '').replace(/\/+$/, '');
  } else if (routeKey === 'simulacion/computational-simulation') {
    specific = String($env.N8N_WEBHOOK_BASE_SIMULACION || '').replace(/\/+$/, '');
  } else if (['trillizo/audit-rotation', 'trillizo/shadow-check'].includes(routeKey)) {
    specific = String($env.N8N_WEBHOOK_BASE_TRILLIZO || '').replace(/\/+$/, '');
  }
  return (specific || fallback).replace(/\/+$/, '');
}

const suffix = routes[routeKey];
const requestId = 'orch-' + crypto.randomUUID().slice(0, 8);
const receivedAt = new Date().toISOString();
const metaPartial = () => ({
  request_id: requestId,
  chosen_route: routeKey,
  incoming_route: route,
  canonical_route: routeKey,
  received_at: receivedAt
});

if (!suffix) {
  return [
    {
      json: {
        orchestrator_error: true,
        error_code: 'INVALID_ROUTE',
        error_message: 'Ruta desconocida: ' + route + (route !== routeKey ? ' (alias→' + routeKey + ' no resuelto)' : ''),
        orchestrator_meta: metaPartial()
      }
    }
  ];
}
const vmsg = validatePayload(routeKey, forward_body);
if (vmsg) {
  return [
    {
      json: {
        orchestrator_error: true,
        error_code: 'VALIDATION',
        error_message: vmsg,
        orchestrator_meta: metaPartial()
      }
    }
  ];
}
const base = webhookBaseForRoute(routeKey);
if (!base) {
  return [
    {
      json: {
        orchestrator_error: true,
        error_code: 'NO_WEBHOOK_BASE',
        error_message: 'Definir N8N_WEBHOOK_BASE o N8N_WEBHOOK_BASE_SENSORES|SATELITES|SIMULACION|DRONES|TRILLIZO para esta ruta',
        orchestrator_meta: metaPartial()
      }
    }
  ];
}
const forward_url = base + suffix;
return [
  {
    json: {
      orchestrator_error: false,
      forward_url,
      forward_body: forward_body,
      orchestrator_meta: { ...metaPartial(), resolved_path: suffix }
    }
  }
];
